  outcome_id: RESILIENT-000
  evidence: |
    COMMAND: grep -c "consensus_result" .chump-locks/ambient.jsonl
    OUTPUT: 0
    
    COMMAND: ps aux | grep "chump-coord worker" | grep -v grep
    OUTPUT: (empty -- subscribe-side daemon not running)
    
